#include<iostream>
#include<cstdio>
#include<cstring>
#include<queue>
#include<vector>
using namespace std;

typedef int cost_t;
const int MAXN = 100010;
const int MAXM = 2000020;
const int INF = 1000000000;

struct Edge {
    int next, to, cap;
    cost_t cost;
} edges[MAXM];

int head[MAXN], edge_cnt = 1, total_nodes;
vector<int> adj[MAXN];

void add_edge(int u, int v, int cap, cost_t cost) {
    edges[++edge_cnt] = {head[u], v, cap, cost};
    head[u] = edge_cnt;
    edges[++edge_cnt] = {head[v], u, 0, -cost};
    head[v] = edge_cnt;
}

namespace MCMF {
    int cur[MAXN];
    bool visited[MAXN];
    cost_t dist[MAXN], potential[MAXN];

    struct Node {
        int node_id;
        cost_t priority;
        Node(int id = 0, cost_t p = 0) : node_id(id), priority(p) {}
        bool operator<(const Node& other) const {
            return priority > other.priority;
        }
    };

    priority_queue<Node> pq;

    bool dijkstra(int source, int sink) {
        for (int i = 1; i <= total_nodes; ++i) {
            dist[i] = INF;
            cur[i] = head[i];
        }
        dist[sink] = 0;
        pq.push(Node(sink, 0));

        while (!pq.empty()) {
            int u = pq.top().node_id;
            pq.pop();
            if (visited[u]) continue;
            visited[u] = true;

            for (int i = head[u]; i; i = edges[i].next) {
                int v = edges[i].to;
                cost_t w = potential[u] + edges[i ^ 1].cost - potential[v];
                if (edges[i ^ 1].cap && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push(Node(v, dist[v]));
                }
            }
        }

        for (int i = 1; i <= total_nodes; ++i) {
            potential[i] = min(potential[i] + dist[i], (cost_t)INF);
        }

        if (!visited[source]) return false;
        for (int i = 1; i <= total_nodes; ++i) visited[i] = false;
        return true;
    }

    int dfs(int u, int sink, int flow) {
        if (u == sink || !flow) return flow;
        int pushed = 0;
        visited[u] = true;

        for (int &i = cur[u]; i; i = edges[i].next) {
            if (edges[i].cap) {
                int v = edges[i].to;
                int f;
                if (!visited[v] && potential[v] + edges[i].cost == potential[u] && 
                    (f = dfs(v, sink, min(flow, edges[i].cap)))) {
                    edges[i].cap -= f;
                    edges[i ^ 1].cap += f;
                    pushed += f;
                    flow -= f;
                    if (!flow) break;
                }
            }
        }

        visited[u] = false;
        return pushed;
    }

    int max_flow;
    cost_t min_cost;

    void solve(int source, int sink) {
        while (dijkstra(source, sink)) {
            int flow = dfs(source, sink, INF);
            max_flow += flow;
            min_cost += (cost_t)flow * potential[source];
        }
    }
}

int source_node = 1, sink_node = 2, n, m, k, c, d;

inline int get_id(int t, int x) {
    return t * n + x + 2;
}

void build_layer(int t) {
    total_nodes += n;

    for (int u = 1; u <= n; ++u) {
        for (int v : adj[u]) {
            for (int p = 1; p <= k; ++p) {
                add_edge(get_id(t, u), get_id(t + 1, v), 1, d * (2 * p - 1));
            }
        }
    }

    for (int u = 1; u <= n; ++u) {
        add_edge(get_id(t, u), get_id(t + 1, u), INF, 0);
    }

    add_edge(get_id(t + 1, 1), sink_node, INF, c * (t + 1));
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    total_nodes = n + 2;

    for (int i = 1; i <= k; ++i) {
        int a;
        scanf("%d", &a);
        add_edge(source_node, get_id(0, a), 1, 0);
    }

    for (int i = 1; i <= m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    add_edge(get_id(0, 1), sink_node, INF, 0);

    for (int i = 0; i <= n + k; ++i) {
        build_layer(i);
    }

    MCMF::solve(source_node, sink_node);
    printf("%d\n", MCMF::min_cost);
    return 0;
}
